    },
    {
      "claim": "L4 permeability and L5 gut-wall efflux/intestinal-metabolism records are for other molecules (celecoxib, tamsulosin, compound 2c, indapamide, PF-06282999, M11, trantinterol, compound 7l, compounds 82/87) and are formulation-, species-, or compound-specific; they do not affirmatively establish F<20% for chlorothiazide.",
      "card_ids": ["C48","C49","C50","C51","C52","C53","C54","C55","C56","C57","C58","C59","C60","C61","C62","C63","C64","C65","C66","C67","C68","C69","C70","C71"]
    },
    {
      "claim": "No direct absolute oral bioavailability or intestinal absorption measurement for chlorothiazide is present; the unfavorable passive-permeability prior (low logD, high TPSA, partial ionization) is insufficient to override the HCTZ exposure, L1 sulfonamide F values, and L6 low-clearance context.",
      "card_ids": ["C36","C37","C38","C39","C41","C42","C44","C45","C46","C72","C81"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "hepatic_clearance_metabolic_stability",
